<div style="display:flex;gap:0.5rem;justify-content:flex-end;margin-top:1rem">
    <button type="button" onclick="document.getElementById('header-action-save')?.click()" style="border:1px solid #2563eb;background:#fff;color:#2563eb;padding:0.5rem 0.75rem;border-radius:0.375rem" onmouseenter="this.style.background='#2563eb';this.style.color='#fff'" onmouseleave="this.style.background='#fff';this.style.color='#2563eb'">إضافة</button>
    <button type="button" onclick="(document.getElementById('header-action-save-and-new')||document.getElementById('header-action-save'))?.click()" style="border:1px solid #2563eb;background:#fff;color:#2563eb;padding:0.5rem 0.75rem;border-radius:0.375rem" onmouseenter="this.style.background='#2563eb';this.style.color='#fff'" onmouseleave="this.style.background='#fff';this.style.color='#2563eb'">إضافة وبدء إضافة المزيد</button>
    <button type="button" onclick="document.getElementById('header-action-cancel')?.click()" style="border:1px solid #ef4444;background:#fff;color:#ef4444;padding:0.5rem 0.75rem;border-radius:0.375rem" onmouseenter="this.style.background='#ef4444';this.style.color='#fff'" onmouseleave="this.style.background='#fff';this.style.color='#ef4444'">إلغاء</button>
</div>
